import type { MeaningPack } from '../../types';

export const enHksC: MeaningPack = {
  lang: 'en',
  texts: {
    'harikathamrutasara-23': {
      summary: "Kalpa-sadhana sandhi: the means (sadhana) by which the different classes of souls fit for liberation attain direct vision (aparoksha) of the Lord and then moksha. It tells how many births or kalpas each class needs (karma-yogis, jnana-yogis, bhakti-yogis, with Brahma and Vayu highest), lists the names of Vayu from the Vamana Purana, and closes with the reckoning of time.",
      verses: {
        '0.0': "With the grace of the guru I will tell the Harikathamrita-sara; may the supreme devotees of the Lord listen to it with reverence.",
        '0.1': "O Madhvacharya, best of gurus, you refuted the false arguments of the founders of the twenty-one (rival) schools and established that Hari is supreme. Look on me with the gracious glance of Lakshmi's Lord, whose glory Brahma and Shiva praise.",
        '0.2': "Without noticing my faults, and as the good-hearted listeners and Chakra-gadadhara (Hari) make me speak, I shall tell the means (sadhana) of the souls eligible for liberation, then the direct vision (aparoksha), and the breaking up of the subtle body (linga). The text of this verse is partly unclear.",
        '0.3': "Beings from grass and worms up to brahmins, animals, the best of men, kings and human gandharvas, who are karma-yogis (those who reach the goal through right action), worship the Lord through an image or symbol (pratika) and offer to Hari all actions of the senses without ceasing; thus they become free of the sense of \"mine\". The text is partly unclear.",
        '0.4': "The class of souls of seven kinds is very large and its numbers are fixed. Taking a human body and birth in a brahmin family, they give up merely outward rituals, understand what the gurus taught, and offer to Hari the duties proper to each time; these are the karma-yogis.",
        '0.5': "After wandering through many kinds of wombs because of low actions, a soul at last attains human birth. With the knowledge and devotion that Hari is supreme, it does faultless actions as the Veda prescribes for a thousand births and offers them to Hari; after that,",
        '0.6': "for ten births they worship Hari as supreme, worshipped by gods and demons, of wondrous deeds, sorrowless, of endless forms, true in will, the cause of creation, maintenance and dissolution, and free of old age and death; after that,",
        '0.7': "for three births, the wise (suris) who love Hari without break, more than they love body, home, cattle, wealth, wife, friends, sons, mother and father, pass beyond the births described, see the Supreme Self within their own body and rejoice.",
        '0.8': "Among the gods, those born as gods and the ancient divine ancestors are always jnana-yogis; Pushkara, Shani, Usha, Svaha-devi, Budha, Sanaka and the sages, the cloud-gods and Parjanya are, within these two groups, the vijnana-yogis. The text here is partly garbled.",
        '0.9': "Taking a hundred births in Bharata-khanda and doing selfless good deeds, then in ten thousand births gaining great knowledge, and in a further series of bodies (the numbers are unclear in the text) practising devotion to the Limitless Lord, they come to see his image-form (bimba).",
        '0.10': "Before their sadhana these souls had no direct vision from time without beginning; they commit no forbidden acts and have no entry into hell. Resolving the seemingly contradictory statements of the Vedas and shastras, they praise Madhusudana as the highest of the highest.",
        '0.11': "From Brahma, lord of Satyaloka, down to all the groups of gods, all are called bhakti-yogis at all times. Among those fit for devotion, Brahma, Vayu, Vani and Bharati are the highest of the highest because of true devotion, knowledge and other qualities.",
        '0.12': "In Brahma and Vayu (the \"straight\" ones) devotion and the other qualities are innate and grow in order up to the rank of Brahma; worship of the image-form (bimba) is greater in them, and they are free from sin. The passions born of the three gunas do not exist in them, but they are found in Garuda, Shesha, Rudra, Indra and the like. The text of this verse is partly unclear.",
        '0.13': "Before sadhana, the sattvika gods such as Ijya are called, from time without beginning, ordinary (samanya) aparokshis. After sadhana they see their own image-form (bimba) with reverence, like the unobstructed sun, each according to their eligibility.",
        '0.14': "Garuda, Shesha and the other gods are called chinna-bhaktas (those whose devotion is limited). The four unbroken devotees (acchinna-bhaktas) are Bharati, Prana (Vayu), and the two Vagdevis (Brahma and Sarasvati). Dwelling as inner controllers within Shiva (the third-eyed one) and others, they carry on their activities.",
        '0.15': "Pavamana (Vayu) does both the low and the good actions; with no doubt of this, to those who worship him with firm devotion Prana's Lord is pleased and gives no low births. But those people who say \"I do all the actions\" he sends to hell.",
        '0.16': "Remaining within beings such as ancestors, kings and men, he does and has them do their natural actions, in one form. The future Brahma (Vayu), in tortoise form, bears the Brahma-egg (universe) on his back and protects the worlds in his second form.",
        '0.17': "Hidden in the souls of the fourteen worlds, Vayu does and makes them do the 21,600 breath-repetitions (the natural japa of breathing) day by day, like a trusted friend through sleep, dream and waking, and gives them their allotted enjoyments; and at the end, in a third form,",
        '0.18': "Even when a soul is in a pure sattvika body the subtle body (linga-deha) does not bind it, like a burnt cloth (it keeps its shape but cannot bind). Among all those who have achieved their sadhana, the blameless Garuda, Shesha, Rudra and the other gods are called servants (dasas) of the Lord. The text is partly garbled.",
        '0.19': "After a hundred kalpas of sadhana he is called Kalki, and at the close of the stated period, in the forms of Vayu, Hanuman and Bhima, he destroys all the demons and is named Madhvacharya. The first part of the verse is unclear.",
        '0.20': "Taking a form like Hari's, Pavamana together with Brahma, Sarasvati and Bharati, in eternal devotion, abides within the Shrutis that declare the Lord's forms and qualities to be of pure knowledge, not perishable; the sentence continues in the next verse. The text is partly unclear.",
        '0.21': "Taking the three crore forms called Kheta, Kukkuta and Jalata, he always destroys the wicked and protects all good people. He is, at all times, for Garuda, Shesha, Shiva and the chief gods, the first gate of Vishnu's city.",
        '0.22': "One among those who has done sadhana for a hundred kalpas is called by a most auspicious name in every kalpa; when the wise praise and bow to him, terrible sins vanish and the Lord of Rama (Lakshmi) is pleased with them at all times. The text is partly unclear.",
        '0.23': "A litany of names, each with a plea for protection, in praise of the Lord of Sarasvati (Vayu), taken from the Vamana Purana: \"Protect me, Kalki, Sutejas, Dasa; protect me, destroyer of dharma and adharma, Varchasvi; salutations, Sadhu, Mahipati; protect me, Saddharmajna, Dharmaja, Sampurna, Shuci, Vaikrita, Anjana, Sarshapa, Kharpata, Shraddhaha.\" (Some names are uncertain.)",
        '0.24': "The litany continues: \"Protect me, Sandhyata, Vijnana; Mahavijnana, Kirtana; Sankirna, Katthana, Buddha, Jaya; Sumahattara, Suvirya; protect me, Medha, Vijaya, Jaya, Rantimna, Manu.\" (Names uncertain in places.)",
        '0.25': "The litany continues: \"Protect me, Moda, Pramoda, Santasa; Ananda, Santushta; Charvanga, Charu, Subahu, Charupada; Sulochana; Sarasvata, Suvira; Prajna, Kapilampata, Sarvajna.\" (Names uncertain in places.)",
        '0.26': "The litany continues: \"Protect me, Sarvajit, Mitra; destroyer of sin; Dharmavineta, Sharada, Oja, Sutapasvi; Tejasvi; Danasushila; Yajnasukarta, Yajvi, Yagavartaka; salutations.\" (Names uncertain in places.)",
        '0.27': "The litany continues: \"Protect me, Prana, Trana, Amarshi; Upadeshta, Taraka; Kalakridana, Sukarta, Sukalajna; Kalasusuchaka; Kalisamharta, Kali; Kala, Shyama, Reta, Sadarata, Subala.\" (Names uncertain in places.)",
        '0.28': "The litany continues: \"Protect me, Sahas, Sada, Kapi; Gamya, Jnana, Dashakula; Shrotavya, Sankirtitavya, Mantavya, Kavya; Drashtavya, Sakhya; Gantavya, Kravya; Smartavya.\" (The text is garbled and the names uncertain.)",
        '0.29': "The litany ends: \"Protect me, Sevya, Subhavya; Svargavya, Bhavya; Jnatavya, Vaktavya, Gavya; Latavya; O Vayu; Brahma, dear to brahmins; protect, protect, Lord of Sarasvati, best of world-teachers.\" (Names uncertain in places.)",
        '0.30': "Those who lovingly remember every day these most auspicious names of the great one, told in the Vamana Purana, the Lord of Lakshmi grants whatever they desire and keeps them happy in his threefold abode.",
        '0.31': "Vayu got a hundred births of great happiness and enjoyed his destined fruits, and reached lordship over the worlds without effort. Is it surprising that the best servant of the Lord, who gave special bliss to the brahmin Sudama for a handful of flattened rice, becomes lord of the world?",
        '0.32': "For two hundred kalpas he is called by this name without break; placing the gods under him, he carries out their sadhana. Destroying the demons such as Kali, he reaches the post of the golden lotus-born (Brahma), together with his wife (Bharati). The text is partly unclear.",
        '0.33': "Vayu, called by the name Animisha (god) in one kalpa, becomes Brahma for eighty-seven and a half years. The worship of the Lord's auspicious qualities, actions and forms, he who is free of the three gunas, goes on from the unmanifest (avyakta) down to the earth. The text is partly unclear.",
        '0.34': "Without saying this, the fault of the group having \"only one highest\" without exception would arise. Equality (in knowledge) can come to the liberated Brahma; knowledge and devotion grow up to the rank of Brahma, worship continues, and afterwards comes the vision of the image-form (bimba). The text is garbled; only this general sense is clear.",
        '0.35': "The Puranic passages that speak of fear and ignorance in Brahma are meant to delude the demons: how could delusion, ignorance, fear and grief belong to the four-faced one? Like the sun's disc seeming to move through a fault of the eye, it was shown only to please Srinivasa, and not otherwise.",
        '0.36': "Brahma is always the best of all, with no one equal or superior, through pure devotion, knowledge, dispassion and other qualities. Learning the Lord's qualities through Lakshmi, he sees the image-form of the Lord forever, like crores of suns.",
        '0.37': "Knowledge and devotion grow in proportion; all the qualities such as knowledge and devotion that are in Brahma are thought of as in Mukhya Prana (Vayu). In the lower groups of souls they are slightly less and grow in order; in Bharati and Vani they are equal. The text is partly unclear.",
        '0.38': "Like the sun, the Lord is seen indistinctly in Brahma, Vayu, Gayatri and the Sarasvati-Bharati pair until liberation. By Hari's grace, even at the great dissolution, faults such as ignorance do not come to Brahma, Vayu, Vani and Bharati.",
        '0.39': "After a hundred years (of his life), Brahma calls those of his kalpa who are to attain liberation, bathes with his own family in the sacred river in Hari's city, and enters Hari's belly.",
        '0.40': "After entering Vasudeva's belly, the faultless liberated souls come out of it with joy, take the Lord's permission, and move about without sorrow, dwelling in the moksha-world of Shvetadvipa on Ananta's seat. The text is partly unclear.",
        '0.41': "Sattva-sattva is extremely subtle; the body of Brahma, lord of Satyaloka, is made of it, with two gunas only very slight. It is not fit for liberation (as a body) and is not the cause of the egg-universe's origin; he performs the world's tasks only to please Hari. The text is partly unclear.",
        '0.42': "Having studied for nearly a hundred years, he did tapas for ten kalpas in the salt ocean under the name Ugratapas, and then attained the post of Mahadeva; at the end of the stated number of kalpas he will reach the rank of Shesha, together with Parvati. The numbers are unclear in the text.",
        '0.43': "For ten kalpas, under the name Sunanda, he listened to teaching about the direct vision of Mukunda; then four kalpas of tapas, a crore of years in smoke, which Purandara (Indra) consumed; afterwards he reached his own world, as did Kama, Lord of the gods, likewise. The verse is garbled; the sense given is partial.",
        '0.44': "Chandra, Arka and others are called earlier by names such as Shanta and Surupa; they hear (the teaching) for two kalpas each, practise tapas, and after about five thousand years of sorrow-free (blessed) time they see the image-form (bimba). The verse is garbled; the sense given is partial.",
        '0.45': "Shiva, Indra and the other gods attain liberation after direct vision, each after a stated number of kalpas of sadhana in this order (fifty and twenty-two for some, sixteen for the Manus and so on). The numbers in the text are partly garbled.",
        '0.46': "The text continues the list of kalpas: twelve for the (other) wind-gods, ten for the Sun and Dharma, nine good kalpas for Mitra, eight for Shesha's group, seven for the sages Sanaka, Sunandana, Sanatkumara and others, six for Pushkara and Parjanya and others. The text is partly unclear.",
        '0.47': "Five kalpas for the karma-born gods, four for the ajanaja gods, three and a half for the gopika women, three for the ancestors; the human singers (gandharvas) get two, kings one, and within half a kalpa direct vision comes. The text is partly unclear.",
        '0.48': "As light follows the lamps, spreads, dispels deep darkness and benefits others, so the Supreme Self, abiding in Brahma and others, reveals his own power and shines, doing and making them do their actions.",
        '0.49': "Giving bodies within his own belly to Prana, Rudra, Indra and other gods, he, the ocean of joy, knowledge and compassion, lovingly accepts their service. He removes the mental and physical ailments of his own people and, without noticing their great offences, protects those who ever remember him.",
        '0.50': "In every kalpa, doing creation, maintenance and dissolution, he rejoices; he makes the four-faced one and Pavamana his food and eats them; the gods called Mrityunjaya and others are the ghee and condiments for Sripati, who nourishes souls as a pregnant woman does. The text is garbled; the sense is partial.",
        '0.51': "As the child in the womb eats what the pregnant woman eats, so the fearless Lord eats and feeds all souls. (Some ask:) How can a weak, minute soul take gross food? Such is said by the naive; the learned do not agree.",
        '0.52': "Because what is eaten there does not decrease, there is no increase either; among the gods no one is a match for him; there is no birth and the like, no beginning. The Lord of boundless glory, Narahari, kind to the wretched, makes his refugees non-returning (they never return to samsara) and gives them the bliss of his own abode. The text is partly unclear.",
        '0.53': "As a farmer sows seed in the earth, waters it, raises the crop, and finally reaps and eats it, so Lakshmi's Lord takes in the worlds; then again, creating, maintaining and dissolving the souls' karma and time, he remains impartial, without grief or joy, ever.",
        '0.54': "Hunger and thirst are present even in Vayu, Rudra, Indra and other gods; they serve as means to all enjoyment, torment demons, ghosts and spirits, and daily stay for a time in humans, animals and birds before leaving. The text is partly unclear.",
        '0.55': "Vasudeva is free of dream, deep sleep, thirst, hunger, fear, grief, delusion, fatigue, forgetfulness, envy, pride, and of merit and sin and similar faults. Thus Brahma, Sadashiva and all the gods worship him and are always liberated. The text is partly unclear.",
        '0.56': "The verse begins to give the measures of time, from the extremely minute kshana through truti, lava and nimesha up to the ghati; sixty ghatis make one day and night (ahoratra). The numerical details in the text are garbled.",
        '0.57': "Fifteen days and nights make a fortnight (paksha), two fortnights a month, two months a season, three seasons an ayana (half-year), two ayanas a year. The four yugas beginning with Krita total twelve thousand years in the gods' reckoning, which I shall explain.",
        '0.58': "In divine years: Krita yuga four thousand eight hundred, Treta three thousand six hundred, Dvapara two thousand four hundred, and Kali twelve hundred; together these make twelve thousand years of the gods.",
        '0.59': "In human years the yugas are: Krita seventeen lakh twenty-eight thousand (as the tradition counts; the text here is garbled), Treta twelve lakh ninety-six thousand, Dvapara eight lakh sixty-four thousand, and Kali half of this latter, four lakh thirty-two thousand.",
        '0.60': "Added together, the four yugas come to forty-three lakh twenty thousand human years. A thousand such cycles, as the wise count, make one day of Brahma, namely four hundred and thirty-two crore years (the text's figures are garbled).",
        '0.61': "For this Brahma (Shatadhriti), thirty days make a month and twelve months a year; within a hundred such years the creation, maintenance and dissolution of all souls takes place. The Shrutis and Smritis call all this a mere moment for Achyuta, the eternally blissful. The last line is unclear.",
        '0.62': "The Vedas and Puranas say that this measure of time is only a figure of speech for Madhava, who has no beginning, middle or end. Through the grace of the blissful Lord, Rama (Lakshmi), Brahma, Rudra, Indra and the rest attain their own posts and enjoy happiness.",
        '0.63': "The joy of drinking the nectar of these stories does not come to the lustful and the scattered-minded; but Jagannatha Vithala, the mine of compassion, in his kindness loves and protects those who give up worldly talk and read this with delight.",
      },
    },
    'harikathamrutasara-24': {
      summary: "Bimba-aparoksha sandhi: how the Lord, the original (bimba) of whom every soul is a reflection (pratibimba), abides in prakriti and in all beings in forms such as Turiya, Vishva, Taijasa and Prajna; how everything is his image (pratime) and how the devotee should see and worship him in everything. Many verses are garbled in the text and only their clear sense is given.",
      verses: {
        '0.0': "With the grace of the guru I will tell the Harikathamrita-sara; may the supreme devotees of the Lord listen to it with reverence.",
        '0.1': "The verse names the Lord's image-forms (bimba) in souls: Turiya in the liberated, Vishva in the living-liberated, Taijasa in those attached to the cycle of birth, and Prajna for the others. However powerful, he does not himself author their sorrow and joy, which come to those who arrive at the end of a kalpa. The text is garbled; only this general sense is clear.",
        '0.2': "Within prakriti, called \"food\" (anna), he is named Prajna; Taijasa in those who eat food, beginning with the sacrificer; and Vishva, with different names and actions. Delighting in himself, he is fullness of bliss and knowledge. The text is partly unclear.",
        '0.3': "Like fire hidden in ash, the Lord is within prakriti and the soul, called \"Anna\" (food) and \"Annada\" (eater); in the forms of Brahma and Shiva he is Vishnu, the giver of the cooked rice, who gives great joy and satisfaction. Who can describe the wondrous work of the Lord of such depth of glory?",
        '0.4': "Constantly contemplate the lotus feet of the Lord: in the food and the act of eating, in the bindu (the dot of the sacred syllable), in the sound in water, in the digestive fire within called Shanta, in Vedic sound, and in sons, brothers and followers, the supremely peaceful (Atishanta) Lord.",
        '0.5': "He is the Lord of Rama (Lakshmi), the master of the Vedas, to be worshipped by Rama, the ocean of qualities, free of the three gunas, holding all universes in his belly yet distinct from them, approved by the good; the Shruti (\"ni shu sida ganapate\") speaks of him as the lord of the hosts, without ever reaching the limit of his qualities. The text is partly garbled.",
        '0.6': "The Lord of Maya, as the Purusha in three places, abiding within Mahat-tattva, made the Brahma-egg, the male and female, the subtle elements, the eleven senses and the great elements. The verse is partly garbled.",
        '0.7': "Abiding with Shri as the Purusha in the bodies of the three gunas, he established for souls the pairs: desire, greed, ignorance, pride, envy, delusion, hunger, laughter, joy, deep sleep, dream, thirst, waking, birth, existence, death, sin and merit, victory and defeat.",
        '0.8': "Having clothed souls like armour in a body of three gunas and made them wander in the stream of karma, the Lord of Maya casts delusion on them and is the cause of samsara; yet for those who hear (shravana) and reflect (manana) he is the liberator.",
        '0.9': "Knowing that he dwells in women and men (the eaters, named Ashana), worship and please them with faith; the sufferings of the best of the immovable ones too he removes. To those who worship him as the eater (Ashana-rupa) he shows his own form. The text is partly unclear.",
        '0.10': "Meditate in another manner too: I shall reveal, as far as my understanding goes and by the power of the guru's grace, the forms Vishva and the rest in this prakriti. As a man entering a house built of mirrors sees his own form everywhere, so the straight-hearted Lord appears everywhere in the moving and unmoving.",
        '0.11': "He abides in prakriti in three divisions, taking forms such as Vishva and, within these three (Atma and the rest), the bright knowledge-self; remember Vasudeva, named Turiya, as the giver of the bliss of liberation. The text is partly unclear.",
        '0.12': "The father of Brahma, abiding in the moving and unmoving, does and makes them do actions in order and in reverse, without weariness; among gods and demons he is meditated on with \"I, mine, salutation\" at the end of the worship. The text is garbled and the sense given is partial.",
        '0.13': "\"All this world is pervaded by the Lord\" (Isha Upanishad): though the world as effect perishes, its cause, prakriti, is eternal. For Shri's Lord even the inert images are never without his presence, like the eternal Shalagrama stone in which he dwells. The text is partly unclear.",
        '0.14': "The one Lord without a second, abiding in many souls, does each one's action separately and deludes them without letting them know; he is called by names within this body such as dumb, deaf and blind. What can I say of the unworldly glory of Lakshmi's Lord? The text is partly unclear.",
        '0.15': "Friend and lord of the worlds, sorrowless, destroyer of his devotees' sorrow, worshipped by Shri, he is within everyone like a touch; the ocean of grace, praised by Shiva, protects the good and accepts all the actions offered by those who bow to him.",
        '0.16': "Body, house, children, wife, wealth, things of metal, wood, stone and clay are his beneficial images (pratimas). Knowing daily that the Supreme Self gave them to me out of love, and without being deluded by attachment, worship the One who has every name. The text is partly unclear.",
        '0.17': "To Shri's Lord the souls are conscious images; pervading all like warp and weft, he conducts their activity as the offerer in all the senses, lovingly eating and feeding, fearless like a lamp in a windless place. The text is partly unclear.",
        '0.18': "As a possessed man speaks much, the world acts by Vishnu's pervasion; these are not mere figures of speech. The five groups of souls under Shesha's hood-umbrella are always called by the names of his (different) feet. The text is garbled; the sense given is partial.",
        '0.19': "\"Three feet are in heaven, one on earth\": thus, praised by the wise, he is called four-footed (Chatushpat). Bringing his four feet to samsara, remember him unceasingly as Uddhava's friend, the inner self of all.",
        '0.20': "Bow without doubt to the servants of Krishna, destroyer of Kamsa; if one is proud, \"I am a scholar\", he binds one with the gunas of samsara. The opening comparison (a bamboo that bends and grows, an acrobat climbing a pole tied with rope) is garbled in the text.",
        '0.21': "To the Lord who is light itself, these are images set up by symbolic attribution: the seven dhatus (body constituents), courage, valour, generosity, skill, speech, honour, greatness, forbearance, good conduct, a pure place, the brahmin, the five elements, the intellect and the seats of the senses. The text is partly unclear.",
        '0.22': "Among souls he is the immortal; among the immovable he is Sthanu; ever abiding as unconquered and endless, he is Govinda's Lord (?), fond of song, with a form, of a thousand names, lord of high and low, of holy deeds, the wise, the abode of nectar. The text is partly garbled.",
        '0.23': "Forbidden acts done to earn wealth for Madhava's worship are counted as meritorious; but good acts done daily merely to fill one's own belly lead to another body, without doubt. The text is partly unclear.",
        '0.24': "Without any support himself, dwelling in all, beyond compare and of incomparable form, he is like a bewitching enchanter, father of Kama; his body shines with the radiance of crores of suns, and in forms like Krishna he eats and feeds everywhere. The text is partly garbled.",
        '0.25': "As a herb that grows unsown in the forest removes the illness in the bodies of all beings, so when devotees call \"O father of Brahma, lord of the three worlds, comfort us!\" he comes to where they are, without exceeding their wish. The text is partly unclear.",
        '0.26': "The abode of Shri stays always close to his own people, as if attached to their bodies, with nothing between. Whatever he gives, take and enjoy, moving about like a rutting elephant; without asking for anything else, keep worshipping his lotus feet. The text is partly unclear.",
        '0.27': "He gives unasked to the gods and, when asked, to men; to the demons who beg and suffer he never gives the true goal. To fools who do dharma only for worldly ends he gives worldly fruits, drives them mad, and then gives great hell.",
        '0.28': "As the sun spreads its rays everywhere and each object, following it, shows its own shadow, so the Lord who holds the discus, as Sankarshana, abides in the world of moving and unmoving beings as shade and heat, in the way fitting to each one's capacity.",
        '0.29': "In this manner, everywhere, together with Lakshmi, Bhu and Durga, filling all places with special portions of himself, he is both the most worthy of service and, himself, a servant; the Lord of Maya-devi, entering all, serves; he is the refuge, the eternal, the compassionate, the lotus-eyed. The text is partly garbled.",
        '0.30': "The one taught by the Pranava as cause and effect, the Highest beyond the highest, distinct from the sentient and the insentient, full of endless true auspicious qualities, incomparable, worshipped, ocean of virtues, sinless, unconquered, endless, dear to the destitute, unchanging, without support, unmanifest. The text is partly garbled.",
        '0.31': "The Harikathamrita is a lamp-wick for the darkness of the fear of samsara and the home of all happiness. Jagannatha Vithala, the Lord of the senses, abides near and delivers his devotees from the great sorrow of worldly existence. The text is partly unclear.",
      },
    },
    'harikathamrutasara-25': {
      summary: "Arohana-taratamya sandhi: the ascending order of rank (taratamya, the gradation of excellence among beings) from the immovable, grass and worms, through animals, the human classes, gandharvas, ancestors and the many orders of gods, up to Brahma, Vayu and Lakshmi, with Lakshmi's greatness set against the Lord's infinite qualities; it ends with the fruit of reciting this order and a string of names of the Lord. Some verses are garbled in the text.",
      verses: {
        '0.0': "With the grace of the guru I will tell the Harikathamrita-sara; may the supreme devotees of the Lord listen to it with reverence.",
        '0.1': "Compared with the immovable, grass and worms are higher; above worms come the goat, sheep, cow, elephant, tiger and lion; above these are the three classes beginning with Shudra, then Brahmins above the other workers, the learned above ritualists, then poets, and kings are higher still.",
        '0.2': "Above kings are human gandharvas, then the gods' gandharvas, each rank far higher than the last by the stated measure; the great sages and apsara women are their equals; above these are the Chira-pitrs (the ancient ancestors), and above them the ancestors called Chira (the verse continues in the next). The text is garbled.",
        '0.3': "The ascent continues through the sage Tumburu, Urvashi and the other apsaras, the hundred ajanaja gods (those born as gods), and the Chira-pitrs; above Urvashi come the two daughters of Vaishvanara and, among the eight thousand wives, the highest of them. The verse is badly garbled; only these names and the idea of rising rank are clear.",
        '0.4': "Equal to these are the women of Vraja (the gopikas). Above the sons of the gods' mouth (Agni's line) is Pushkara; above him Shani (Shanaishchara); above the Sun's son, Usha and the Ashvins; then Varuna (Jalapa); Budha, Chandra's son, is higher; above him is Svaha-devi.",
        '0.5': "Above Agni's wife (Svaha) are the unnamed (anakhyata) gods; above them Parjanya; Usha (Aniruddha's wife), Ganga, Sanjna, Shyamala and Rohini, these six, are equal and higher than the unnamed gods; above them are the hundred karmaja gods (those who became gods through deeds).",
        '0.6': "Kings such as Prithu, Nahusha, Shashabindu, Priyavrata and Parikshit, then Bhagirathi/Bhagiratha, are higher; then come the seven Indras beginning with Bali, the pitrs, the apsara women, the Manus, Shukra (the demons' guru), and the sages Chyavana and Uchathya, who are all equal as karmaja gods. The text is partly unclear.",
        '0.7': "Kubera, Vishvaksena, Ganapa and the Ashvins (the number eighty-five is given for the Shesha-group's equals), Mitra, Tara, Nirriti and Pravahi are named; higher are the great sages Marichi, Pulastya, Pulaha, Kratu, Vasishtha and others. The text is garbled and the counts are unclear.",
        '0.8': "Angirasa and the other of the seven sons of Brahma are equal to them; Vishvamitra and Vaivasvata (Manu), by the power of the Lord's entry (avesha) in them, are higher than Mitra; higher than these are Svaha's husband (Agni), Bhrigu, Prasuti and others, three who are the highest. The text is partly garbled.",
        '0.9': "Narada is higher than Agni; the lord of the waters (Varuna), Yama, the Moon, the Sun and Shatarupa are higher; above the Sun is Pravaha-Maruta (the Pravaha wind); above Pravaha come Aniruddha (Kama's son), Guru (Brihaspati), Manu, Daksha, Shachi and Rati, six in all. The text is partly unclear.",
        '0.10': "Above these six is the Ahankarika-prana (the vital principle presiding over the ego); then the Prana that rules the whole body; higher than him are Kama and Indra; then Gauri, Varuni and Garuda's wife; among Hari's queens Jambavati, being united with Rama (Lakshmi), is counted higher. The text is partly garbled.",
        '0.11': "Hara (Shiva), Phanipa (Shesha) and Vihagendra (Garuda), these three, are higher than Hari's queens; Bharati and Vani are higher than the lord of Suparni (Garuda); above these two are Marut (Vayu) and Brahma; Indira (Lakshmi) is the highest of all, and none is ever her equal in place or time.",
        '0.12': "What can I say of the great glory of Lakshmi, Mukunda's consort? She brings about the creation, maintenance and dissolution of Brahma, Shiva, Indra and the others and provides each with their abode; herself free of old age and death, she worships Achyuta as \"Lord of all, my guru\".",
        '0.13': "Though Lakshmi has such glories, she is never equal even to a tiny fraction of the Lord's infinite qualities, at any time. For Lakshmi, who is beyond space and time, Keshava's chest alone became her abode; can anything be compared to his greatness and pervasion?",
        '0.14': "In a single form, a single limb, a single hair, a single place of his are held all the groups of souls from Brahma downwards, the seven oceans, the seven islands, Meru, Mandara and other mountains, and all the worlds from Brahma's and Indra's down to the lower ones.",
        '0.15': "He is the best of all gods, all-pervading, full of all qualities, giver of all, wholly independent, support of all, Self of all, faced everywhere, bearing every name, worshipped by all, eternal, giver of all desires, witness of all, and conqueror of all.",
        '0.16': "Those who write down and recite this ascending order of rank (taratamya) win the favour of Lakshmi-Narasimha, the inner self of all the groups of gods. The compassionate Lord fulfils their wishes, grants kaivalya (liberation) and removes all sins, leaving them free of fear and grief.",
        '0.17': "For one who longs to see the feet of the Lord who grants wishes to those who bow, this ordered ascent from the inert up to the Brahma-egg is a ladder. For those who recall it in mind and speech it dries up the ocean of samsara and becomes the cause of the wealth of knowledge, devotion and dispassion. The text is partly garbled.",
        '0.18': "The Lord who is offered in the fire (homa), sandalwood and the like, is perceived in each of them with a distinct fragrance at all times. Vrijinardana, the destroyer of sin, brings out the suitable and unsuitable actions of demons, humans and gods; he is famed as beyond the three gunas.",
        '0.19': "Dear to devotees, the fortunate Person, distinct, the support of the universe, ever-abundant, far from all faults, hard to reach and hard to conceive, supremely capable, eternal, declared by all the Vedas, giver of honour and worthy of honour, Madhava, subtle and gross, Lord of the three worlds, Jagannatha Vithala.",
      },
    },
    'harikathamrutasara-26': {
      summary: "Avarohana-taratamya sandhi: a litany of salutations in descending order of rank, beginning with Keshava, Lakshmi, Brahma, Vayu and Sarasvati and going down through Garuda, Shesha, Shiva, the Manus, sages, and the other classes of gods to the lowest, asking each for knowledge, devotion and dispassion; it ends with the fruit of remembering this order daily.",
      verses: {
        '0.0': "With the grace of the guru I will tell the Harikathamrita-sara; may the supreme devotees of the Lord listen to it with reverence.",
        '0.1': "With joy I bow to Keshava, Narayani (Lakshmi), Brahma, Vayu, Vani, Garuda, Shesha and Mahesha (Shiva), to the feet of the six queens, to the wives of Shesha and Rudra, to Indra and Pradyumna (Kama), praying that they grant me devotion and knowledge.",
        '0.2': "I bow to Prana-deva; to Kama's son (Aniruddha), Manu, Guru (Brihaspati), Daksha, Shachi, Rati and the other ladies; to Pravaha-deva; Surya, Soma, Yama and Yama's consort; Varuna; and to the sage Narada, vina in hand, that they may teach me the path of knowledge, devotion and dispassion.",
        '0.3': "I bow always to Agni, Bhrigu, Dakshayani, the seven sages born of Brahma, Vaivasvata Manu, Gadhi's son (Vishvamitra), Nirriti, Tara, Pravahi, Mitra, the Ashvins, Ganapa, Kubera and Vishvaksena (and others named; the text is partly unclear).",
        '0.4': "I bow to the remaining gods and the further eighty-five persons, to the Manus, to Uchathya and Chyavana and the twins, to the karmaja gods led by Kartavirya Arjuna and the hundred (shatastha), and to the feet of the consorts of Parjanya, Ganga, the Sun, Yama, Soma and Aniruddha. The text is garbled; the sense is partial.",
        '0.5': "I bow every day, without break, to Agni's wife (Svaha), Budha son of Chandra, Usha, Shani son of Chhaya, and to the lotus feet of Pushkara, who presides over the actions that all souls perform. The text is partly unclear.",
        '0.6': "I bow constantly to the ajanaja gods, to Agni's sons, to the women living in the cow-station (the gopis), to the Chira-pitrs, to the hundreds and crores (of lesser gods), to the sages, deva-gandharvas, human gandharvas, skilled singers, kings, and to the whole company of servants of Rama's Lord.",
        '0.7': "Those who remember this order of rank daily with true devotion find that dharma, wealth, desire and the rest bear fruit. Bow humbly to Jagannatha Vithala, of whom Brahma and the others are the limbs, and keep praising him without forgetting.",
      },
    },
    'harikathamrutasara-27': {
      summary: "Anukramanika-taratamya sandhi: a short closing salutation to the followers of Madhvacharya's school and to all the true gods in order up to Lakshmi-Narayana, followed by a string of epithets of the Lord as the family deity, wish-granting and wholly independent, eternal, without internal difference, ending with Jagannatha Vithala who never leaves those who remember him day and night.",
      verses: {
        '0.0': "With the grace of the guru I will tell the Harikathamrita-sara; may the supreme devotees of the Lord listen to it with reverence.",
        '0.1': "I bow to the lotus feet of the wise who follow the school of Shrimad Acharya (Madhva), to those worthy of drinking soma, to the whole company of true (tattvika) gods, to Haimavati (Parvati) and the six queens' ranks, to Shiva (Vyomakesha), Vani, Vayu, Brahma, Lakshmi and Narayana.",
        '0.2': "Best of the fortunate, Lord of Shri, giver of good wishes, gentle one, abode of the three heights, of holy deeds and beautiful limbs, lover of cows, supremely worthy as guru, fond of the Sama chant, Lord of all, my family deity: may he comfort the good. The text is partly unclear.",
        '0.3': "Rama, terror of the rakshasa clan, beloved of the elephant-king (Gajendra), beyond the reach of mind and speech, giver of the bliss of knowledge, of beautiful deeds, the Full One, for his own devotees everywhere he is the wish-fulfilling cow, wish-tree and wish-jewel for earth, heaven and liberation.",
        '0.4': "Golden-hued, independent, all-pervading, without ears, a good bed to rest on, eternal, beyond the four castes and four stages of life, delighted in himself, taught by the syllables of the Veda, with Garuda (Suparna), Vayu's friend, as his noble vehicle, the sleeper on the banyan leaf, most wondrous, of good conduct, full of virtues. The text is partly unclear.",
        '0.5': "Abode of countless virtues, unmoving, free of internal differences (svagata-bheda, difference within his own being), eternal, utterly distinct from the world and the souls, protector of those who depend on him, beyond the three gunas, Lord of the three worlds: Shri Jagannatha Vithala, the all-pervading, does not leave those who remember him day and night.",
      },
    },
    'harikathamrutasara-28': {
      summary: "Ganapati sandhi: a prayer to Ganesha, the son of Shiva, a servant and bee at Hari's lotus feet. The poet asks him to remove obstacles, to give discernment, devotion, knowledge and dispassion, to keep the mind and senses from the world, to help him praise the Lord daily, and ends by offering this garland of twenty-one verses to Jagannatha Vithala, the Lord who dwells within Ganesha. Some verses are garbled in the text.",
      verses: {
        '0.0': "With the grace of the guru I will tell the Harikathamrita-sara; may the supreme devotees of the Lord listen to it with reverence.",
        '0.1': "O Ganesha, bee at the lotus feet of Shri's Lord, son of Mahesha (Shiva), shine in my mind every day. I pray with overflowing love: protect the good. You, object of the grace of Veda-Vyasa, lord of the great sky, merciful one, take my hand and lift us up.",
        '0.2': "One-tusked, elephant-faced, your body adorned with gold ornaments, look on me with a merciful glance: this is my plea. Grant us always the joy of the company of the discerning who praise the Lord worthy of praise, O most merciful one.",
        '0.3': "King of obstacles! My mind is sunk in evil sense-objects; may it become fastened with devotion to the lotus feet of the Lord who destroys great faults. I fear the fires of hell; O best of gurus, destroy my vices day by day.",
        '0.4': "You are counted equal to Kubera, Vishvaksena and the Ashvins (the divine physicians), O younger brother of Shanmukha, best among the \"hundred\" group of gods; praised in the heavenly Ganga and a worshipper of the Lord. With a pure mind I pray: protect us by giving devotion and knowledge of Lakshmi's Lord. The text is partly unclear.",
        '0.5': "By the boon of Gauri's husband (Shiva) you were born as Charudeshna in Rukmini, and at Krishna's command destroyed the arrogant rakshasas and lightened the burden of the earth. Compassionate one, I bow to your lotus feet; grant us good understanding.",
        '0.6': "You shine like the rising sun, with a serpent for waist-cord, a strange form and holy conduct, holding the goad and the noose in your hands, breaker of the pride of the wicked, witness of all deeds. Be the one who satisfies the good with contentment.",
        '0.7': "Lord of the sky, with supreme devotion you studied the works composed by Vyasa and, without effort, wrote them down and spread them in the world. Noose-holder, I pray: teach me their meaning; ocean of compassion, look on me with a merciful glance every day.",
        '0.8': "You who dwell in the pure navel-region of Shri's Lord, your body beautified by red sandal paste, purifier of the world, friend of the gods, riding the mouse, filled with Prana (Vayu), famous lord: fulfil the wishes devotees ask for, every day.",
        '0.9': "Son of Shankara, to give terrible fates to the demons, you appear as the deity of Sankata-chaturthi (the fourth day that removes distress); you give them harmful things and bewilder the dull. Branded with the discus-bearer's mark, I bow to your lotus feet and plead daily: protect me.",
        '0.10': "Your lotus feet are worshipped by Siddha and Vidyadhara groups, giver of all attainments: quickly grant my petition. Give me intellect, learning, knowledge, strength, pure devotion and dispassion, and in my mouth the praise and remembrance of the Lord's sports.",
        '0.11': "Adorned with two red garments, listen to my prayer, O best of the supreme devotees of the Lord. Let my mind be attached to the Bhagavata and the other scriptures; give me dispassion toward the objects of the senses and, from day to day, make me known as freed from the fear of samsara. The text is partly unclear.",
        '0.12': "Indra worshipped you to destroy Shukra's disciples (the demons); the Lord Rama worshipped you at the start of the causeway; emperor Dharmaraja (Yudhishthira) worshipped you at the word of the discus-bearer (Krishna). O Vakratunda, how great Ishvara's favour is in you!",
        '0.13': "The Kaurava king (Duryodhana) did not worship you and so met destruction with his whole clan; Vrikodara (Bhima), the excellent guru, killed them with his mace. Younger brother of the slayer of Taraka (Skanda), stay in my body as the impeller of dharma and comfort me with compassion. The text is partly garbled.",
        '0.14': "Fond of twenty-one modakas, you make the dumb eloquent; ocean of grace, grateful, giver of wishes, protect me. Foremost of scribes, take my hand and remove the distress of my mind; son of Pinakin's wife (Parvati), formed of clay, I pray to you with compassion. The text is partly garbled.",
        '0.15': "Grant me the good fortune of constantly remembering, and rejoicing in, the Lord who is eternal, of auspicious deeds, controller of the creation, maintenance and dissolution of the world, giver of the three knowledges, liberator from bondage, who acts according to the mental tendencies of gods and demons, never negligent, kin of the good.",
        '0.16': "Make the knowledge of the five differences (pancha-bheda: God and soul, God and matter, soul and soul, soul and matter, matter and matter) clear to me, and show the Father of Brahma in my mind. Giver of wishes, knowing me out of love as your servant, son of the five-faced Shiva, do not deceive me in samsara but protect me, and keep my mind and senses from roaming among the sense-objects.",
        '0.17': "I ask nothing from you but this: I fear the evil births. Grant us the true knowledge that Lakshmi's Lord, the Lord of Prana, together with the lords of the tattvas (the presiding deities), himself does the work of the gunas; O great one, I plead only this, again and again.",
        '0.18': "Salutations to you, best of gurus, best of the wise, ever wakeful, a wish-tree to your worshippers, full of many virtues and of auspicious conduct, son of Uma. Remove my ego and sense of \"mine\": the intellect and senses attack me and wear me out in samsara at all times.",
        '0.19': "Victory to you, Vighnesha, destroyer of the three kinds of suffering, auspicious to the whole world, giver of knowledge, free of fear and grief! Victory, fair-limbed one! Look on your devotees with compassionate eyes and remove birth, disease and death from them in samsara.",
        '0.20': "Knowing you are most compassionate, I bow my body at your feet; ocean of compassion, always protect me without leaving. Hold back the obstacles that come now and then, and, without forgetting, make me every day speak and make me chant the praises of the Lord's names.",
        '0.21': "This new garland of lotuses made of twenty-one verses at the feet of Ganesha, son of Mainaki (Parvati): may Shri Jagannatha Vithala, the Lord of Prana, who dwells within him, accept it, and at all times give his devotees the joys of heaven and liberation. The text is partly garbled.",
      },
    },
    'harikathamrutasara-29': {
      summary: "Anu-taratamya sandhi: a compact restatement of the descending order of rank (taratamya) from Vishnu, the highest, through Lakshmi, Brahma and Vayu, Sarasvati and Bharati, Garuda, Shesha and Shiva, the queens, Indra and Kama, the sages, the soma-drinking gods, kings and men, down to the immovable, the eternally bound, the demons and Kali at the very bottom. It ends by showing that Vayu inspires the actions of all three kinds of souls, and that Lakshmi's Lord alone is supreme. Some verses are garbled in the text.",
      verses: {
        '0.0': "With the grace of the guru I will tell the Harikathamrita-sara; may the supreme devotees of the Lord listen to it with reverence.",
        '0.1': "Vishnu is the highest of all; Prakriti (Lakshmi) is lower than he; Brahma and Pavana (Vayu), of endless qualities, are lower than she; Vani and Bharati lower again; Garuda, Shesha and Shiva are lower than these; Krishna's queens are lower than these, and among them Jambavati is called the best by the power of the indwelling (of Lakshmi).",
        '0.2': "The wives of Garuda, Shesha and Shiva are equal among themselves and lower than Jambavati; Indra and Kama are lower than they; their Prana (the life-principle of the ego) is lower still; Kama's son (Aniruddha), Shachi, Rati, Daksha, Guru (Brihaspati) and Manu, these six, are lower than him, and Pravaha-Maruta is lower than the six. The text is partly unclear.",
        '0.3': "Yama, the Sun, the Moon and Yama's wife are equal and lower than Pravaha; Varuna is lower than the Sun, and Narada lower still. Agni (the gods' mouth), Prasuti and the sage Bhrigu are equal, lower than Narada; Atri and others, Vishwamitra and Vaivasvata (Manu) are lower than Agni. The text is partly garbled.",
        '0.4': "Mitra, Tara, Nirriti and Pravaha's wife Pravahi are equal and lower than Vishwamitra; Vishvaksena, Ganapa (Ganesha), Kubera and the Ashvins are lower than Mitra and the others. Next I shall explain the group names of the gods of the \"hundred\" (shatastha) class.",
        '0.5': "Know these as entitled to drink soma: the forty-nine Maruts, the two Ashvins, the ten Vishvedevas, the eleven Rudras, the twelve Adityas, the Guru and Pitrs, the eight Vasus, Bharata, Bharati, Prithvi and the Ribhus.",
        '0.6': "Among the gods named, fifteen (and the remaining eighty-five of the hundred) are rated alike, including Kubera and Vinayaka (the wording is unclear). The sages Vaivasvata, Svayambhuva, Shridatapasa and the other Manus, eleven in all, are lower than Vinayaka.",
        '0.7': "Chyavana's son, Kavi (Shukra), Brihaspati and his younger brother Uchathya, Agni, Dhruva, Nahusha, Shashabindu, Priyavrata, Prahlada and Kuvalayashva are lower than those named before; lower again are Rohini, Shyamala, Jahnavi (Ganga), Virat, Parjanya and Sanjna-devi. The text is partly garbled.",
        '0.8': "Lower than Ganga are the non-presiding gods (those not presiding over any tattva) and the sages called Kechana; Svaha is lower than they; Budha lower; Usha lower; Shani lower; Pushkara, the lord of karma, praised by the good, is lower than the Sun's son.",
        '0.9': "Lower than these come the eighty (ashiti) sages and others; then Urvashi and the hundred leading apsaras and Tumburu and others, who are called ajanaja (born as gods); then the groups of Agni, then the Anakhyata (nameless gods), apsara women and gopis, and, among humans, the gods who came as men. The text is partly garbled.",
        '0.10': "Below them are the nameless apsara women and the good ladies who are companions of Krishna's person; after them the Chira-pitrs; lower than them the gandharva groups of the gods; lower than these the human gandharvas; and lower than these the lords of the ocean-girdled earth (kings), each a hundredfold in qualities.",
        '0.11': "The hundred best men are lower than kings by a hundredfold; those a hundredfold higher in each successive stage (the higher beings), when constantly thought of and bowed to by devotees who say \"I am your servant\", dwell in their hearts and bestow every happiness.",
        '0.12': "Trees, creepers, grass and shrubs are lowest in order; lower than the eternally bound souls (nitya-baddha, those who never leave samsara) are the ignorant; lower still are the servants of those fit for darkness (tamas), and the demons who preside over anger and the like, Namuchi and others, with Vipraciti lowest of them. The text is partly unclear.",
        '0.13': "Alakshmi (misfortune) is low; Kali is the lowest of the low; in all the three worlds no sinner is left beyond him. The knowing are to keep up this reflection constantly, even at the time of relieving oneself, in darkness, and in unclean or evil places.",
        '0.14': "Brahma presides over the sattvika souls; among the eternally bound, the demon Puranjana (?) and, as lord of the hosts of demons, Kali; Pavamana (Vayu) is always within them as the inciter of action, himself doing and making them do it, for the pleasure of Shri Purushottama. The text is partly garbled.",
        '0.15': "Prana-deva, most skilled among the three kinds of souls, does and makes them do their actions according to each one's eligibility: he gives knowledge and devotion to the gods, mixed knowledge to the middling souls, and ignorance, delusion and hatred to the demons.",
        '0.16': "Having understood in this way the ranks of gods and demons, and knowing that Lakshmi's Lord is the highest of all, serve him daily. Jagannatha Vithala, full of bliss, praised by Brahma and the gods, lovingly gives happiness everywhere to the devotees who serve him.",
      },
    },
    'harikathamrutasara-30': {
      summary: "Daitya-taratamya sandhi: the ranking of the demons (daityas), the souls who hate Hari and are bound for blind darkness (andhantamas, the lowest of the infernal worlds). It lists the marks of a demonic outlook (ascribing faults to the Lord, denying the differences among his forms and the gods' ranks, worshipping gods apart from him), then ranks demons by name from Kali upward, tells of their fall when Vayu's mace breaks their subtle body, says that censuring demons brings no sin, and closes with the Lord giving each its due fruit. Several verses are garbled in the text.",
      verses: {
        '0.0': "With the grace of the guru I will tell the Harikathamrita-sara; may the supreme devotees of the Lord listen to it with reverence.",
        '0.1': "Brahma said: \"As much devotion and knowledge as I have in you, Vayu has in the same measure. The demon who, not knowing this, speaks of differences among Hanuman and the other incarnations is fit for terrible blind darkness, without doubt. I shall seize the tongue-tip of those who revile you and cut it off.\"",
        '0.2': "A demon is one who says that the Lord, who is full of knowledge, power and bliss and all-pervading, has inferior qualities; who says \"I too am Ishvara\"; who says that the Self of being-consciousness-bliss is born; who dwells on Lakshmi's separation from the Lord; or who says that weapons threaten the body that cannot be cut or divided.",
        '0.3': "A demon is one who ascribes the faintest fear or grief or suffering to the Lord who is free of fear and grief; who gives the forms of Rama and Vyasa an ordinary brahmin or sage status; who says the forms of Dasharathi and Krishna had their hair cut like ordinary people; or who says that (Krishna) worshipped Shiva for the sake of children.",
        '0.4': "A man is a demon who says that Rama set up (a linga) to remove sin; who thinks of a difference between the Lord's form and the Lord himself; or who says that rivers, holy waters, guru, mother, father, master, images and compassionate beings are themselves \"the gods\". The text is partly unclear.",
        '0.5': "A demon is one who calls the beautiful, self-manifest forms (of the Lord) mere consciousness-bliss while bowing to an Ishvara made by humans; or who says that Shiva, the Sun and Hari are one, calls the Sun best of gods and worthy of the world's worship, and thus slights Vishnu. The text is partly unclear.",
        '0.6': "A man who regularly places pure Shalagrama stones at the peepal tree, tulasi and Shiva (the moon-bearer) and bows to them is fit for liberation. But one who, out of desire for dharma, wealth, liberation or pleasure, bows to these apart from the Shalagrama meets sorrow. The text is partly garbled.",
        '0.7': "A man who, leaving aside the Lord of vast glory, bows separately to the gods is just a demon; Hari is not present in that worship. But one who bows to Lakshmi's Lord, knowing that he dwells within Brahma and all the other gods, is never left by him even for half a moment.",
        '0.8': "Whoever devoutly serves, as ends in themselves, such things as Mahadeva as worshipped by the Shaiva and Shudra, Vayu, Hari's images, tulasi in Vrindavana for two months, a barren cow, or peepal trees without the marriage rite is a demon and meets eternal sorrow. The verse is garbled; this is only its general sense.",
        '0.9': "In the line from Brahma down through the best of men, the liberated are equal; a person with a hundred years of life (Brahma's counterpart) is Kali, and in the same order the demons descend, down to the lowest of men, those among the asuras with hatred and similar qualities being the base. The verse is badly garbled; only this general sense is clear.",
        '0.10': "Kali, the one named by the word Mahakali, stands as counterpart to Brahma's hundred years. Day by day the demons who follow Kali's path fall into blind darkness (andhantamas); awaiting the end of Brahma's hundred years, at that end their subtle body (linga) is broken by the blow of Vayu's mace.",
        '0.11': "After Vayu's mace destroys the subtle body, they reach the door of darkness (tamas) and experience the sufferings of their own nature. Enmity toward Hari and his devotees exists in them in gradation, strongest in Kali, the highest degree in samsara and in tamas.",
        '0.12': "The \"knowledge\" of the demons is false and improper, a wave of sorrow. Kali's wife is a hundredfold lower than Kali; Vipracitti is lower by a stated measure (one hundred less); Kalanemi was born as Kamsa. The text is partly unclear.",
        '0.13': "Madhu and Kaitabha took birth on earth and were called Hamsa and Dibhika; Vipracitti, named Aila, is placed equal to Hiranyakashipu; Hiranyakashipu, a devotee of Shulapani (Shiva), and Naraka a hundredfold lower. The verse is garbled; the sense given is partial.",
        '0.14': "Kanaka (Hiranyaksha) and Kashipu are ranked low in the three qualities; Hatakamba is equal to Manimanta; Baka is slightly lower than Manimanta; Taraka, the chief of demons, is lower by twenty-fold; Shambara, the thorn of the world, is lower than Taraka by six-fold. The text is partly unclear.",
        '0.15': "The demon Shankara is equal to Salva and ten-fold lower (than the one before); Shambara is six-fold lower; Hidimba, Banasura, Dvapara and Kichaka, these four, are equal; Dvapara was the name of Shakuni, maternal uncle of the Kauravas. The text is partly unclear.",
        '0.16': "Namuchi, Ilvala and Paka are equal; Bana and others are ten-fold lower; Namuchi is lower by a hundredfold, then the evil-minded Vatapi, then Dhenuka a hundredfold lower; the enemy of the gods (Vatapi?) is lower than Dhenuka, and Keshi is lower by half than Dhenuka. The text is garbled.",
        '0.17': "Again, Trinavarta, named like Keshi, is equal; Lavanasura is nine-fold lower; Arishta five-fold lower; the demon-chiefs Hamsa, Dibhika, the arrogant Vena and Paundraka are eighty-fold lower; below Lavana come Duhshasana and the others. The verse is garbled; the sense given is partial.",
        '0.18': "Duhshasana and Vrishasena, foremost demons, are equal to Jarasandha; among sinners Kamsa is the highest; Kupavikarna is equal to Rukmi, who is lower by a hundredfold; the great demon Shatadhanvi and Kirmira are a hundred-fold lower than Rukmi. The text is partly unclear.",
        '0.19': "Among the wine-drinking groups of demons, the Kalakeyas are lowest; by the power of divine indwelling they are equal to their superiors. The demons who preside over the mouth, hands, feet, ear, anus, genitals, nose, skin and the act of eating are lower than the Kalakeyas.",
        '0.20': "Kali and the other demons who preside over the senses of knowledge and action make and have the low deeds done in all beings. Vani, Bharati, Brahma and Pavamana are unbroken (acchinna) devotees, free from demonic indwelling, firm as an unbreakable stone. The text is partly unclear.",
        '0.21': "Agni, Akshadya and the other gods all come under the indwelling of Kali and the demons; this is not so in the incarnations of Brahma, Marut (Vayu), Sarasvati and Bharati. With folded palms, standing before his father, he bowed and pleaded, \"Show me your favour.\" The speaker is unclear in this garbled verse.",
        '0.22': "Do not doubt the gradation of the hating demons, nor count their slander as ornaments, for one who does meets many sorrows. Vedavyasa told this to the sages in the Garuda Purana. The verse breaks off in the text.",
        '0.23': "Thorns, caltrops and sharp stones trouble a barefoot man; one who wears leather sandals has no fear of thorns, scorpions or snakes. So one who rejoices to hear that a scorpion or snake has been killed incurs no sin, and a man who censures the demons has no fear of Yama's servants. The text is partly garbled.",
        '0.24': "Keep offering your good deeds to the Lord, Brahmanya-deva, who dwells within Brahma (Pushkara, Hiranyagarbha). The sorrow that arises from merit and sin he lets Kali and the others eat. The refuge of all the worlds, the eternal one gives mixed fruit to mixed people. The text is partly unclear.",
        '0.25': "The Lord of Lakshmi, presiding over the three gunas, in those who have the gunas gives each the fruit of their actions according to each one's fitness; he gives without limit of number to the gods and demons who are under his control. Best of gods, Jagannatha Vithala, all-pervading.",
      },
    },
    'harikathamrutasara-31': {
      summary: "Naivedya-prakarana sandhi: on the food offering (naivedya) to the Lord. It opens with praises of Hari under many epithets, then names, for each item of the meal (rice, milk, ghee, butter, curd, sweets, pulses, vegetables, sour and pungent things, salt, fruit juices, water, betel, spices), the form of Hari and the deity who abide in it, so that the devotee may eat remembering him; it closes by describing the plate's mandala and boundary line and by teaching that Hari himself is both worshipper and worshipped. Some verses are garbled in the text.",
      verses: {
        '0.0': "With the grace of the guru I will tell the Harikathamrita-sara; may the supreme devotees of the Lord listen to it with reverence.",
        '0.1': "He brought forth Brahma from his navel and the gods from his limbs, and protects them like children; the slayer of rakshasas who always, as Partha's charioteer, protected him in battle, free of sorrow and full of joy. The opening words of the verse are unclear.",
        '0.2': "Free of the faintest trace of fault, taking many forms, of wondrous deeds, the wise one, Lord of Maya, enthroned in Madhva's heart, sleeping on Shesha, the refuge, his fair neck adorned with the Kaustubha, ever delighted, essence of strength and beauty: what can I say of his glory?",
        '0.3': "The Shruti (\"one of the two birds eats, the other does not eat but looks on\") speaks of two forms of Keshava, within and outside the conscious body. The wise, tirelessly worshipping with true devotion, always praise him as abiding like fire (the eater of oblations).",
        '0.4': "Full of all good qualities, far from birth and all other faults, manifest and unmanifest, of good action, free of samsara, slayer of Kamsa, of many forms, controller and (also) the controlled one, free of ailment, shining like the sun: Lord, always protect me, my nearest kin. The text is partly unclear.",
        '0.5': "Lakshmi's Lord, pervading the conscious and unconscious world as himself and taking the forms of each being within it, abides in everyone's speech like a mimic or showman; he makes all actions be done without letting himself be known, and watches and smiles.",
        '0.6': "Fearless, giver of true knowledge, lord of past, future and present, enemy of the wicked, rider of Garuda, beloved of Lakshmi, carefree, dear to Vayu, the ancient one, taker of Putana's life, father of Brahma, beloved of the wise: protect us, protect us.",
        '0.7': "Slayer of the wicked, of most exalted glory, praised by Vayu, giver of all desires, self-delighted, blissful, my family lord; joyful, nourished, youngest (kanishtha), the one who ordains creation, grant-giver to the elephant-king, giver of what we wish, noble in deeds: I bow to you always.",
        '0.8': "Whose feet Indra worships, whose glory Shiva praises, destroyer of Sita's grief, easy to approach, fair-faced, golden-hued; husband of Lakshmi, the wise one, foe of Madhu, the one without a second, inner self of the host of gods and their images: protect us.",
        '0.9': "Immeasurable, of endless nature, ever of gracious lotus-face, giver of the bliss of liberation, whose lotus feet the gods worship, self-luminous, independent, all-going, quick giver of fruit, Lord of earth, hero of the Yadus, beyond reasoning; who as Vishva, Taijasa and Prajna (the three states of waking, dream and deep sleep) abides in souls.",
        '0.10': "As the wind blows and the dark clouds move with it, so Brahma, Shiva (the trident-bearer), Indra, the Sun and all the groups of gods, and Mahalakshmi who presides over time, karma and the gunas, follow and act after Hari, the root cause and giver of liberation.",
        '0.11': "Can the effort of one who says \"I will drive away the clouds with a hand-fan\" succeed even at the end of the aeon? (So no one can resist the Lord of Lakshmi.) Doing and causing the paired actions in souls and making them eat the fruits, he is worshipped by the capable, who cross the ocean of samsara.",
        '0.12': "Destroyer of affliction, delusion, ignorance and faults, he fills the Brahma-egg at all times like space; without hurting his own, he protects them without effort, ocean of compassion, with his gracious lotus face; the Vairaja (Virat) form.",
        '0.13': "As the eyes of one who holds a mirror and looks do not rest on the mirror but see their own reflection, so the blessed on earth, leaving aside the mirror (of the world), see your form everywhere, rejoice, praise you and are immersed in the ocean of bliss.",
        '0.14': "Keshava, ocean of compassion, abides in the Moon, who presides over food; Bharati with Narayana in the rich sweet rice (paramanna); in the fried sweets (bhakshya) the golden-rayed Sun with Madhava; in ghee, Lakshmi with Govinda, praised by the Shruti. (The deity and form paired for each item is the point of the verse.)",
        '0.15': "Sarasvati presides over milk: think of Vishnu, essence of the world, there. In the flat bread (mandige) is Brahma with Madhusudana; in butter, Vayu with Trivikrama as the impelling one; in curd, the lord of the waters and the Moon with Vamana.",
        '0.16': "Garuda presides over the lentil soup (soopa) with Shridhara as its deity; the Sun, called Mitra, over leaf and branch, with the form Hrishikesha; the king of serpents (Shesha) over fruit and the good branch, with Padmanabha. The knowing eat at all times remembering these.",
        '0.17': "Gauri presides over everything sour, so know Damodara there; think of Sankarshana in the sour things drunk (Gauri's lord, Shiva's presiding place?); the wise meditate with great reverence everywhere on Vasudeva, who is in sugar and jaggery with Indra (Vritra's foe). The text is partly unclear.",
        '0.18': "Remember Brihaspati in the seasonings, where Pradyumna is; in the pungent things, Yama (Dharma, lord of hell) with Aniruddha; in mustard and asafoetida, Kama (Smara) with Purushottama; and meditate on and worship (the Lord) in camphor with supreme devotion. The text is partly unclear.",
        '0.19': "Among the rasas received by the tongue, such as milk, in the things cooked in ghee and oil, meditate on Adhokshaja, who protects the Moon's son (Budha) there; in the large pumpkin, sesame and black-gram delicacies, Daksha with Lakshmi-Narasimha.",
        '0.20': "Meditate on Achyuta (with the mind-deity) in the delicacies of black gram; remember Janardana in salt (the house of Nirriti); think of Prana with Upendra in fruit juices; and in the betel leaf, Ganga with the form of Hari; praise him and rejoice.",
        '0.21': "Budha presides over sweet water, and the Veda-praised Lord is present there as Krishna, giver of wealth: know this and worship, performing good deeds without ceasing. Pushkara purifies and has purified the offered items and offers them to Hari named Hamsa. The text is partly unclear.",
        '0.22': "Rati presides over all the delicious tastes; think of Vishva there. In the hearths (of fire) think of Bhargava; in cow-dung and the like, Vasanta with Rishabhadeva: praise them always with true devotion. The text is partly unclear.",
        '0.23': "Know at all times Vishvambhara, the sorrowless, with Mahalakshmi, mother of the fourteen worlds. In the cleansed square mandala (where the plate is set), the wise meditate on the Lord called Bhu-sukara (Varaha); above it, on Ekadanta who guards the cloth, and on Sanatkumara. The text is partly unclear.",
        '0.24': "So that no one may look at Srinivasa's food (the enjoyable offering), Vishvaksena is present there as the boundary line (the water-trench drawn round the plate); the Purusha named (Hari) is himself both worshipper and worshipped and comforts his own; the guru Pavamana (Vayu), bowed to at all times and everywhere, is with him.",
        '0.25': "In every new, fine, delicious and pleasing dish, the mother of Brahma (Lakshmi) is the taste itself in each flavour, constantly delighting; with Jagannatha Vithala she is fearless. Knowing this, worship and be happy.",
      },
    },
    'harikathamrutasara-32': {
      summary: "Kakshya-taratamya sandhi (kakshya: class or rank): the closing litany of salutations, class by class, in the order of rank taught in the earlier sandhis. After a prayer to Narahari and to Lakshmi, it bows in turn to Brahma and Vayu, Sarasvati and Bharati, Garuda, Shesha, Shiva, Krishna's queens, Indra, Pradyumna, the lesser gods, sages, ancestors, gandharvas, kings, human devotees and the followers of Madhvacharya, then states the fruit of reciting these verses at the three junctures of the day and ends with a cry of victory to the Lord. Several verses are garbled in the text.",
      verses: {
        '0.0': "With the grace of the guru I will tell the Harikathamrita-sara; may the supreme devotees of the Lord listen to it with reverence.",
        '0.1': "Lord of Shri, Lord of all, all-pervading, enjoyer of the essence, independent, far from faults, full of knowledge, bliss, strength, lordship and virtues; free of the three gunas yet with auspicious qualities and form, cause of the world's creation, maintenance and dissolution, full of compassion, Narahari: protect the good.",
        '0.2': "Addressed to Lakshmi: ever-liberated, changeless, ever full of bliss, support of the eternal and the non-eternal worlds, praised by liberated and unliberated souls; hear my petition. Dweller on Purushottama's chest, protector of (his) servants, mother of the three worlds, renowned one. The text is partly unclear.",
        '0.3': "In each pore of the great Person's skin are, separately, his own forms, the Brahma-eggs and the universal forms within them. Unable to find the limit of Lakshmi's forms and qualities as I ponder, I am amazed again and again: how great is the glory of my Lord!",
        '0.4': "Brahma, unable to find the end of even one of his qualities in one Brahma-egg, in one form, one limb, one nail, said with folded hands, with hair standing on end, tears of joy and faltering words, \"The glory of Indira's Lord is exceedingly deep.\"",
        '0.5': "How blessed are Brahma and Guru Pavamana (Vayu), who lovingly gaze in this way on the pure, overwhelming beauty of Rama's Lord and rejoice! What good fortune of those great ones! When it is out of reach even for Shiva (the husband of Bhavani), what is the plight of men?",
        '0.6': "I bow constantly to Brahma, the Grandfather, who for a hundred kalpas recited the qualities of Lakshmi's Lord and pleased him, and to Vayu who, with great valour, became Hanuman, Bhima and Anandamuni (Madhva); Brahma shines under the name \"born from the navel-well of the Supreme Brahman\".",
        '0.7': "I always bow, with great joy, to Sarasvati and Bharati, who see Vasudeva's form like the moon in the sky of the heart and praise him with great delight, praying that they grant me true knowledge and devotion.",
        '0.8': "May Garuda, lord of the bird-clan, give auspiciousness to all good people: holding the two feet of the Lord of the world (the best of gods) on his own shoulders and in his lotus hands, he sees in the row of nails the lovely reflection of the Mountain-bearer (Krishna), and praises him with great joy and delight.",
        '0.9': "I bow in my mind constantly to the feet of Guru Nagaraja (Shesha), who with two thousand tongues lovingly describes him who is beyond reach of the yogis' hearts and praised alone by the Vedas and Agamas, pervading earth, sky and the nether world, and whose abode of yoga-sleep Shesha is.",
        '0.10': "Destroyer of Daksha's sacrifice, Virupaksha, lord of dispassion, protect us at all times, giving us pure joy; friend of Kubera, wish-tree to those who sacrifice, slayer of the demon Vrika, overseer of the world, and as Shuka, Durvasa and Jaigishavya (forms of Shiva), comfort us.",
        '0.11': "I always bow to Shiva, bearer of the (Ganga) and crescent moon on his crest, three-eyed, slayer of Andhaka, wearing the skins of elephant and tiger, son of Brahma (born of the lotus-seated), worshipped by the three worlds, pure as crystal, lord of Parvati, adorned with a serpent's hoods; protect me always. The text is partly unclear.",
        '0.12': "I bow to Krittivasa (Shiva): who for ten kalpas, in the salt ocean, pleased the One of excellent fame (Hari) and became fulfilled; and who, by the command of the Lord of the world, spread false scriptures, deluded the wicked, and made them dwellers in eternal hell; he is worthy of the post of Shesha.",
        '0.13': "Hooded serpent on the crown, ringing damaru, trident, with the fire, the sun and the moon as his eyes, supremely pure and of holy conduct; granting wishes to those who bow, his feet worshipped by Pramathas, gods and hosts of sages, crusher of Ravana's pride: protect me always, Mahadeva.",
        '0.14': "I bow to the divine lotus feet of the six queens of the conch-bearing Lord: Lakshmana, Jambavati, Kalindi, Nila, Bhadra and Mitravinda, who are dear to him. May they, together with their Lord, dwell without leaving in the sky of my heart.",
        '0.15': "By the Lord's favour they are always aparokshis (direct-seers), knowing the glory of the Lord's forms and qualities from their own husbands' mouths: Suparni (Garuda's wife), Varuni and Parvati (the mountain's daughter). I describe them thus; may they, without counting my great offences, grant supreme auspiciousness. The text is partly unclear.",
        '0.16': "I bow to the feet of Indra, the cloud-rider, who sings like the spring cuckoo, in soft, sweet praise, of Upendra, who shines like a jujube fruit in the heavenly world, the abode of the wishing tree, jewel and cow. The text is partly unclear.",
        '0.17': "Kama (Ratimanohara) in Ketumala-varsha constantly worships Pradyumna, Kriti's husband, of matchless strength, beauty and virtue; I praise his lotus feet with devotion, that, removing my wrong-mindedness, he may graciously and constantly give me right understanding.",
        '0.18': "I bow at the lotus feet of Prana's Lord (Vayu), the great doer of action who presides over the whole body, who in the deep ocean of the nine-fold devotion worships on the serpent-king's seat in the heart of the supremely generous Lord, knowing him to be my guru. The text is garbled; the sense given is partial.",
        '0.19': "Of vast glory, all-faced, of matchless strength of arm, a wish-tree: resorting to him and obtaining all they desire, Rati, Svayambhuva (Manu), Daksha, Vachaspati (Brihaspati), Indra's wife Shachi and Manmatha's son Aniruddha rejoice daily; may they give me supreme auspiciousness.",
        '0.20': "May Pravaha-Maruta, who is the boatman across the ocean of samsara through the lotus feet of hearing, singing and the rest (the nine kinds of devotion), ferrying devotees across without leaving them, bestow on the host of the Lord's devotees a great and ceaseless festival of joy, like a great flowing stream. The text is partly garbled.",
        '0.21': "Saying \"I will uplift the people,\" with your father's consent you lovingly begot good sons through Svayambhuva Manu; mother Shatarupa, I bow to you daily in mind, speech and body, that you gladly give us auspiciousness.",
        '0.22': "You fathered Nara, Narayana, Hari and Krishna; you, Yama (Audumbara), who are counted equal to the Sun, the Moon and Shatarupa, consign sinners to hell and protect the company of the good: protect us, without leaving, with your utmost compassion.",
        '0.23': "Moon, born of the Lord's mind at the time of churning the milk ocean, shining on the head-abode of the mountain-born's husband (Shiva): may my mind, like a bee, bow at your lotus feet. Lord of my mind, I bow daily; remove the inner torment.",
        '0.24': "As the eyes of the lotus-eyed Lord of Shri, giving a hand of support to the good by spreading his rays, the Sun called Vivasvan, Vibhavasu: may he, day and night, give true knowledge on this earth, together with the wise.",
        '0.25': "One who begot the mother of the world and gave her to the one and only Lord of the world: in your house, where he dwells with Shri the maiden, Brahma and the others stand constantly saying \"supreme!\"; ocean of the jewels of virtues, can you be described? Give us a good mind. (The verse does not name the one addressed.)",
        '0.26': "I bow to the divine sage Narada: a tilak shining on his forehead, neck adorned with strings of tulasi beads, a sounding vina in his hand, who, dancing in great joy with sweet voice and many rhythms, sings the qualities of the One taught by the Pranava.",
        '0.27': "May the sage Bhrigu give us all the aims of life: on the bank of the Sarasvati, at the request of the sages, he went to the worlds of Brahma, Mahesha and Achyuta, examined all their qualities, and taught that Keshava alone is the supreme God.",
        '0.28': "By the lotus-eyed Hari's command, becoming the mouth of the gods (Agni) and carrying the oblations of many flavours to each god, he is Yajnapurusha, lord of the Vasu class. I bow to his matchless-strength forms; may he give us knowledge, fame, learning and good understanding.",
        '0.29': "By your father's command you lovingly bore sixty famous children and gave them to their husbands with honour; O Prasuti, mother, equal to Agni, I praise you and bow my head at your lotus feet: protect our family.",
        '0.30': "I bow at the feet of the great ascetic sages who, apart from Brahma's two sons, pleased the Unconquered (Hari) in deep samadhi and shine in the three worlds: Marichi, Atri, Pulaha, Kratu, Vasishtha, Pulastya, Vaivasvata, Vishvamitra and Angiras. The text is partly garbled.",
        '0.31': "Mitra, first of the twelve Adityas; Pravaha's wife Pravahi; Nirriti; and Tara, wife of the gods' guru: may these gods dispel daily the crowd of mental and bodily ailments and lovingly give the wise all auspiciousness at all times.",
        '0.32': "I bow constantly to Vishvaksena, Dhanapa (Kubera) and Gajanana (Ganesha), the honourable ones, and to the eighty-five gods of the \"hundred\" (shatastha) group who are equal to them. May they remove false knowledge, give right understanding and lovingly protect us with prosperity.",
        '0.33': "May the presiding deities of the elements and winds, the ascetic sage Marichi, and Jayanta, Indra's son, who presides over the feet, lovingly protect us always, without making us anxious over worldly objects and without giving a perverse mind at the lotus feet of the Fearless One. The text is partly unclear.",
        '0.34': "The eighty kula-rishis; Haihaya (Kartavirya); Prithu, who made the earth tremble; Parikshit; Nahusha; Nabhi; Yayati; Shashabindu; the seven Indras beginning with Bali: these are called karmaja gods (those who attained godhood through karma). Also the remaining eleven Manus, Uchathya, Chyavana and others. (The text repeats this list in verse 36; the line order seems displaced.)",
        '0.35': "(Prahlada) who, rejecting his own teachers, taught his brothers that Hari is the great primal cause, full of all qualities; when the demon (his father) angrily said, \"Show me that lord of yours,\" he showed in an instant, from the pillar, Shri's Lord. O Prahlada, protect us. The text is partly garbled.",
        '0.36': "The seven Indras beginning with Bali are called karmaja gods; the remaining eleven Manus, Uchathya, Chyavana and the other eighty kula-rishis; Haihaya; Prithu, who made the earth tremble; Parikshit; Nahusha; Nabhi; Yayati; Shashabindu. (This repeats the list of the earlier verse, with the lines in another order.)",
        '0.37': "Priyavrata, Bharata and Mandhata, the virtuous; Jaya, Vijaya and the others; the eight gandharvas; Agni (Hutavaha), Pavaka, Sanatana; the seven Pitrs; and Chitragupta: may they protect us every day, regarding us as their own. The text is partly unclear.",
        '0.38': "Urvashi, who sports in pure waters; Rahu and Ketu, called the enemies of the Moon and the Sun; and the gods called Dhumarchis and others on the path to Shri's feet, who are always equal to the karmaja gods: may these heavenly beings give us auspiciousness. The text is garbled; the sense given is partial.",
        '0.39': "May the goddesses Ganga, Shyamala, Sanjna, Rohini, the wives of Parjanya and of Aniruddha, Virat-devi who presides over the Brahma-egg, and Svaha, Agni's wife, grant me, as I remember them, freedom from obstacles in dwelling on the Lord's qualities. The text is partly garbled.",
        '0.40': "I bow joyfully, constantly, to Budha, who like a bee shines at the feet of Brahma's father (Hari) and is called the presiding deity of the pure waters, praying that he lovingly grant us prosperity.",
        '0.41': "I bow to Devaki, who obtained as her son the birthless Lord, beyond the minds of Brahma and others, and fondled him and watched his sports; and to Yashoda-devi. May they, with a gracious look, protect our line.",
        '0.42': "May the goddesses called Usha and the others, who preside over the pure, auspicious names of Mukunda that purify even the lowly, and the wife of the physicians (Ashvins) of Marut's house, remove the diseases of all the good on earth and protect them every day. The text is partly unclear.",
        '0.43': "When Hiranyaksha stole you (the earth) away, the gods prayed and the Lord, hearing their plea, took the Varaha form and brought you back. Mother Earth, I submit at your feet: please do not count my faults such as touching you with my feet.",
        '0.44': "Clothed in the ocean, adorned with the great mountains as breasts, supporter of the conscious and the unconscious, whose body has the qualities of smell, taste, form and the rest; best of sage-clans, Kashyapa's own daughter: I bow to you; half-body of the Supreme Self, protect me without counting my faults.",
        '0.45': "To punish sinners who do not worship Hari and the gurus, you become Shani (Shanaishchara) and constantly give them bad fruits. Son of the Sun, I bow at your lotus feet; sunk in the ocean of samsara, which is so hard to cross, I must be lifted out.",
        '0.46': "May Pushkara, the guru who presides over the actions of many souls and, by Hari's command, makes them eat at each time the fruit-flavour born of their selfless actions done with supreme knowledge, grant freedom from obstacles in our good deeds. The text is partly unclear.",
        '0.47': "I bow to the sons of Agni (Krishanu), the 16,100 wives of Shri Krishna, the Yakshas, Danavas, Charanas, the ajanaja gods, apsaras and gandharvas, who are the dwelling-place of supreme compassion. The numbers and groups are unclear in this garbled verse.",
        '0.48': "The Kinnaras, Guhyakas, Rakshasas, Nagas, Pitrs, Siddhas, and the praised ajanaja gods are equal to one another, born of the wombs of the gods. How can their hosts be described by me? May they, out of compassion, give joy and splendour to the utterly helpless.",
        '0.49': "I bow to the gopikas: some on the bank of the Yamuna took the Katyayani vow with devotion, some regarded the conch-and-discus-bearing Lord as their husband, some pleased the Lord, father of the Wind, by loving him as a paramour. May they fulfil my desires daily. The text is partly garbled.",
        '0.50': "Setting aside the hundred sages, I join my hands to the lotus feet of the hundred crore ascetics above them, that they may uplift me. Excluding those called by three-sevens-hundred, may the many ancestors who come after these sages give us constant auspiciousness. The text is garbled; the sense given is partial.",
        '0.51': "May the divine gandharvas, who with single mind and attentive, sing in melodious voice and with many graces, in Indra's assembly, the hosts of virtues of Rama's Lord, the purifier of the pure, give us all the aims of life. The verse breaks off in the text.",
        '0.52': "I bow to the human gandharvas who sing the auspicious divine names of Lakshmi's Lord, purifier of the world. Setting aside the best of kings, he (the poet) remembers day after day, with purity of the senses, those called the middling lords of the earth. The text is partly unclear.",
        '0.53': "I bow to the lotus feet of those best of men who, like lightning, see and rejoice in the forms of Shri Mukunda in the sky of the lotus of the heart; may they, giving the desired things, protect the crowd of those who bow. The text is partly garbled.",
        '0.54': "To the groups of great Vaishnavas on this earth who follow the school of the guru Shrimad Acharya (Madhva), bees at Vishnu's lotus feet, I bow; I name them, that at the various watches of the day they may teach me good understanding. The text is partly unclear.",
        '0.55': "Brahma, Vani, Rudra, Indra and the host of other gods are proper recipients of the compassion of Kama's father (Hari). May Rama's Lord (Hari) fulfil their wishes at all times for those who recite these verses on the ranks of the gods (taratamya).",
        '0.56': "Praising (these verses) at the three junctures of the day purifies the body, speech and mind and removes every day the whole crowd of sins; fear of thieves, kings, crocodiles, armies, weapons, water, fire, ghosts, great serpents, fever and hell will never arise.",
        '0.57': "Victory, victory to the Lord distinct from the three worlds; victory to the sole cause of the world; victory to Janaki's husband, free of age and death; victory to the father of Jahnavi (Ganga) and destroyer of the demon clan, healer of the disease of samsara, Jagannatha Vithala: protect me always.",
      },
    },
  },
};
